def transform(grid):
    out = [row[:] for row in grid]
    bg = grid[0][0]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != bg]
    if not pts:
        return out
    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts)
    c1 = max(c for r, c in pts)
    ink = grid[pts[0][0]][pts[0][1]]
    # Complete the object's top and bottom horizontal strokes across its bounds.
    for r in (r0, r1):
        for c in range(c0, c1 + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    # Continue each vertical stroke between its highest and lowest existing cells.
    for c in range(c0, c1 + 1):
        rows = [r for r, cc in pts if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out
